import React, { useState } from 'react';
import { FiBell, FiCheck, FiX, FiCheckCircle, FiAlertCircle, FiInfo } from 'react-icons/fi';

const NotificationBell = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [notifications, setNotifications] = useState([
    { id: 1, type: 'success', title: 'Application Accepted!', message: 'Your application for Web Development was accepted.', time: '5m ago', read: false },
    { id: 2, type: 'info', title: 'New Project Match', message: 'A new project matching your skills is available.', time: '1h ago', read: false },
    { id: 3, type: 'warning', title: 'Profile Incomplete', message: 'Complete your profile to get better matches.', time: '2h ago', read: true },
    { id: 4, type: 'success', title: 'Payment Received', message: 'You received $500 for Mobile App Design.', time: '1d ago', read: true }
  ]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const markAsRead = (id) => {
    setNotifications(notifications.map(n => n.id === id ? {...n, read: true} : n));
  };

  const markAllRead = () => {
    setNotifications(notifications.map(n => ({...n, read: true})));
  };

  const removeNotification = (id) => {
    setNotifications(notifications.filter(n => n.id !== id));
  };

  const getIcon = (type) => {
    switch(type) {
      case 'success': return <FiCheckCircle className="text-green-600" size={20}/>;
      case 'warning': return <FiAlertCircle className="text-yellow-600" size={20}/>;
      case 'info': return <FiInfo className="text-blue-600" size={20}/>;
      default: return <FiBell className="text-gray-600" size={20}/>;
    }
  };

  return (
    <div className="relative">
      {/* Bell Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 text-gray-700 hover:text-green-600 hover:bg-gray-100 rounded-lg transition-all"
      >
        <FiBell size={22}/>
        {unreadCount > 0 && (
          <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center text-xs font-bold animate-pulse">
            {unreadCount}
          </div>
        )}
      </button>

      {/* Dropdown */}
      {isOpen && (
        <div className="absolute right-0 mt-2 w-96 bg-white rounded-xl shadow-2xl border border-gray-200 z-50 animate-slide-down">
          
          {/* Header */}
          <div className="p-4 border-b border-gray-100 flex items-center justify-between">
            <h3 className="text-lg font-bold text-gray-800">Notifications</h3>
            {unreadCount > 0 && (
              <button
                onClick={markAllRead}
                className="text-xs text-green-600 hover:text-green-700 font-semibold flex items-center space-x-1"
              >
                <FiCheck size={14}/>
                <span>Mark all read</span>
              </button>
            )}
          </div>

          {/* Notifications List */}
          <div className="max-h-96 overflow-y-auto">
            {notifications.length === 0 ? (
              <div className="p-8 text-center">
                <FiBell className="mx-auto text-gray-300 mb-3" size={48}/>
                <p className="text-gray-500 font-medium">No notifications</p>
              </div>
            ) : (
              notifications.map((notif) => (
                <div
                  key={notif.id}
                  className={`p-4 border-b border-gray-100 hover:bg-gray-50 transition-all ${!notif.read ? 'bg-green-50' : ''}`}
                >
                  <div className="flex items-start space-x-3">
                    <div className="flex-shrink-0 mt-1">
                      {getIcon(notif.type)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between">
                        <h4 className={`text-sm font-bold ${!notif.read ? 'text-gray-900' : 'text-gray-600'}`}>
                          {notif.title}
                        </h4>
                        <button
                          onClick={() => removeNotification(notif.id)}
                          className="text-gray-400 hover:text-red-500 transition-colors ml-2"
                        >
                          <FiX size={16}/>
                        </button>
                      </div>
                      <p className="text-sm text-gray-600 mt-1">{notif.message}</p>
                      <div className="flex items-center justify-between mt-2">
                        <span className="text-xs text-gray-400">{notif.time}</span>
                        {!notif.read && (
                          <button
                            onClick={() => markAsRead(notif.id)}
                            className="text-xs text-green-600 hover:text-green-700 font-semibold"
                          >
                            Mark as read
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          {/* Footer */}
          {notifications.length > 0 && (
            <div className="p-3 bg-gray-50 rounded-b-xl text-center">
              <button className="text-sm text-green-600 hover:text-green-700 font-semibold">
                View All Notifications
              </button>
            </div>
          )}
        </div>
      )}

      {/* Backdrop */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40"
          onClick={() => setIsOpen(false)}
        ></div>
      )}
    </div>
  );
};

export default NotificationBell;
